// Parse AWS Cost Explorer response and detect a cost spike vs the recent baseline
const response = $input.item.json;
const resultsByTime = response.ResultsByTime || [];
const config = $('Set - Config').item.json;

if (resultsByTime.length < 2) {
  return { json: { ...config, isSpike: false, reason: 'insufficient_cost_data' } };
}

const daily = resultsByTime.map(r => {
  let dayTotal = 0;
  if (r.Groups && r.Groups.length) {
    dayTotal = r.Groups.reduce((sum, g) => sum + parseFloat(g.Metrics.UnblendedCost.Amount), 0);
  } else if (r.Total && r.Total.UnblendedCost) {
    dayTotal = parseFloat(r.Total.UnblendedCost.Amount);
  }
  return { date: r.TimePeriod.Start, total: dayTotal, groups: r.Groups || [] };
});

const todayEntry = daily[daily.length - 1];
const baseline = daily.slice(0, -1);
const avgBaseline = baseline.reduce((s, d) => s + d.total, 0) / baseline.length;

const percentIncrease = avgBaseline > 0 ? ((todayEntry.total - avgBaseline) / avgBaseline) * 100 : 0;

const serviceTotalsToday = {};
(todayEntry.groups || []).forEach(g => {
  const svc = g.Keys[0];
  serviceTotalsToday[svc] = parseFloat(g.Metrics.UnblendedCost.Amount);
});

const serviceBaselineAvg = {};
baseline.forEach(d => {
  (d.groups || []).forEach(g => {
    const svc = g.Keys[0];
    const amt = parseFloat(g.Metrics.UnblendedCost.Amount);
    serviceBaselineAvg[svc] = (serviceBaselineAvg[svc] || 0) + amt;
  });
});
Object.keys(serviceBaselineAvg).forEach(svc => {
  serviceBaselineAvg[svc] = serviceBaselineAvg[svc] / baseline.length;
});

let topService = null, topServiceIncreaseAmount = 0, topServiceIncreasePercent = 0;
Object.keys(serviceTotalsToday).forEach(svc => {
  const baselineAmt = serviceBaselineAvg[svc] || 0;
  const increaseAmount = serviceTotalsToday[svc] - baselineAmt;
  if (increaseAmount > topServiceIncreaseAmount) {
    topServiceIncreaseAmount = increaseAmount;
    topService = svc;
    topServiceIncreasePercent = baselineAmt > 0 ? (increaseAmount / baselineAmt) * 100 : 100;
  }
});

return {
  json: {
    ...config,
    todayCost: Math.round(todayEntry.total * 100) / 100,
    avgBaselineCost: Math.round(avgBaseline * 100) / 100,
    percentIncrease: Math.round(percentIncrease * 100) / 100,
    topService,
    topServiceIncreaseAmount: Math.round(topServiceIncreaseAmount * 100) / 100,
    topServiceIncreasePercent: Math.round(topServiceIncreasePercent * 100) / 100,
    isSpike: percentIncrease >= parseFloat(config.costSpikeThresholdPercent)
  }
};

// GitHub returns commits newest-first; the most recent commit touching the
// Terraform path before the spike is the prime suspect for the root cause
const commits = $input.item.json;
const context = $('JS - Parse Cost Data & Detect Spike').item.json;

if (!Array.isArray(commits) || commits.length === 0) {
  return { json: { ...context, suspectCommitFound: false } };
}

const top = commits[0];

return {
  json: {
    ...context,
    suspectCommitFound: true,
    suspectCommitSha: top.sha,
    suspectCommitMessage: top.commit.message,
    suspectCommitAuthor: top.commit.author.name,
    suspectCommitDate: top.commit.author.date,
    suspectCommitUrl: top.html_url
  }
};

