// Parse the AI's structured fix output and prepare GitHub API payloads
const item = $input.item.json;
const raw = item.output || item.text || item.response || '{}';

let parsed = {};
try {
  const cleaned = String(raw).replace(/```json|```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    rootCauseSummary: 'AI response could not be parsed automatically. Manual review required.',
    suggestedFixDescription: '',
    updatedFileContent: null,
    prBranchName: 'cost-anomaly-fix-' + Date.now(),
    prTitle: 'Investigate cloud cost anomaly',
    prBody: String(raw),
    commitMessage: 'Investigate cloud cost anomaly'
  };
}

const context = $('JS - Identify Root-Cause Commit').item.json;
const fileInfo = $('HTTP Request - Get Current Terraform File').item.json;

return {
  json: {
    ...context,
    rootCauseSummary: parsed.rootCauseSummary || '',
    suggestedFixDescription: parsed.suggestedFixDescription || '',
    updatedFileContentBase64: parsed.updatedFileContent ? Buffer.from(parsed.updatedFileContent, 'utf-8').toString('base64') : null,
    prBranchName: parsed.prBranchName || ('cost-anomaly-fix-' + Date.now()),
    prTitle: parsed.prTitle || ('Fix cost anomaly in ' + context.terraformPath),
    prBody: parsed.prBody || parsed.rootCauseSummary || '',
    commitMessage: parsed.commitMessage || ('Fix cost anomaly in ' + context.terraformPath),
    currentFileSha: fileInfo.sha,
    hasFix: !!parsed.updatedFileContent
  }
};

